CREATE OR REPLACE FUNCTION calculate_discount(amount NUMERIC, discount_percent NUMERIC) RETURNS NUMERIC LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF amount < 0 OR discount_percent < 0 OR discount_percent > 100 THEN RAISE EXCEPTION 'Invalid amount or discount percentage'; END IF; RETURN ROUND(amount * (1 - discount_percent / 100), 2); END; $$;
CREATE OR REPLACE FUNCTION format_price(amount NUMERIC) RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$ SELECT 'INR ' || TO_CHAR(amount, 'FM999,999,990.00'); $$;
CREATE OR REPLACE FUNCTION create_order(p_customer_id INTEGER, p_warehouse_id INTEGER, p_product_id INTEGER, p_quantity INTEGER) RETURNS INTEGER LANGUAGE plpgsql AS $$ DECLARE v_price NUMERIC(12,2); v_stock INTEGER; v_order_id INTEGER; BEGIN IF p_quantity <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than zero'; END IF; SELECT price INTO v_price FROM products WHERE product_id=p_product_id; IF NOT FOUND THEN RAISE EXCEPTION 'Product does not exist'; END IF; SELECT quantity INTO v_stock FROM inventory WHERE product_id=p_product_id AND warehouse_id=p_warehouse_id FOR UPDATE; IF NOT FOUND OR v_stock < p_quantity THEN RAISE EXCEPTION 'Insufficient stock'; END IF; INSERT INTO orders(customer_id,warehouse_id,total_amount) VALUES(p_customer_id,p_warehouse_id,v_price*p_quantity) RETURNING order_id INTO v_order_id; INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(v_order_id,p_product_id,p_quantity,v_price); UPDATE inventory SET quantity=quantity-p_quantity WHERE product_id=p_product_id AND warehouse_id=p_warehouse_id; RETURN v_order_id; END; $$;
